The previous calculator syntax was the issue. I’m now computing the exact finite-state process directly, including all 100 balls and the end-of-ramp behavior, then selecting the ball with the greatest ejection probability.
```python
# Exact probability propagation over platform states.
# Each state is (platform_tuple, next_ball); probabilities are floats.
states = {((), 1): 1.0}
win = [0.0] * 101
discard = [0.0] * 101

for step in range(1000):
    new_states = {}
    active = False
    for (plat, nxt), mass in states.items():
        if not plat:
            continue
        active = True
        k = len(plat)
        for pos in range(k):
            q = mass / k  # empty piston firings are skipped conditionally
            p = plat[pos]
            if pos == 0:
                # Position 1 is struck and ejected.
                if 1 <= p <= 100:
                    win[p] += q
                remaining = list(plat[1:])
            elif pos == 1:
                # Position 2 is struck; position 1 is discarded.
                if 1 <= plat[0] <= 100:
                    discard[plat[0]] += q
                if 1 <= p <= 100:
                    win[p] += q
                remaining = list(plat[2:])
            else:
                # Position 3 is struck; position 1 is discarded.
                if 1 <= plat[0] <= 100:
                    discard[plat[0]] += q
                if 1 <= p <= 100:
                    win[p] += q
                remaining = [plat[1]]
            while len(remaining) < 3 and nxt <= 100:
                remaining.append(nxt)
                nxt += 1
            key = (tuple(remaining), nxt)
            new_states[key] = new_states.get(key, 0.0) + q
    states = new_states
    if not active:
        break

best_prob = max(win[1:])
best_ball = 1 + win[1:].index(best_prob)
ranking = sorted(((win[i], i) for i in range(1, 101)), reverse=True)[:10]
print(f"best_ball={best_ball}; best_probability={best_prob:.12f}; top10={ranking}; steps={step+1}; residual_states={len(states)}")
```

