    reverse=True
)
best_probability_corrected, best_ball_corrected = ranking_corrected[0]
print(f"best_ball={best_ball_corrected}; best_probability={best_probability_corrected:.12f}; top10={ranking_corrected[:10]}; residual_mass={sum(states.values()):.3e}; context_used={len(context_marker)}")
